import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [queues, setQueues] = useState([]);

  const [form, setForm] = useState({
    patientName: "",
    doctor: "",
    department: "",
    date: ""
  });

  const fetchQueues = async () => {
    const res = await fetch("http://localhost:5000/api/queue/all");
    const data = await res.json();
    setQueues(data);
  };

  useEffect(() => {
    fetchQueues();

    socket.on("queueUpdated", fetchQueues);

    return () => socket.off();
  }, []);

  // BOOK OP
  const bookOP = async () => {
    await fetch("http://localhost:5000/api/queue/book", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form)
    });

    setForm({
      patientName: "",
      doctor: "",
      department: "",
      date: ""
    });
  };

  // JOIN QUEUE
  const joinQueue = async (id) => {
    await fetch(`http://localhost:5000/api/queue/join/${id}`, {
      method: "PUT"
    });
  };

  return (
    <div style={{ padding: 20 }}>

      <h2>👤 Patient Dashboard</h2>

      {/* BOOK OP */}
      <div>
        <input
          placeholder="Patient Name"
          value={form.patientName}
          onChange={(e) => setForm({ ...form, patientName: e.target.value })}
        />

        

        <input
          placeholder="Department"
          value={form.department}
          onChange={(e) => setForm({ ...form, department: e.target.value })}
        />

        <input
          type="date"
          value={form.date}
          onChange={(e) => setForm({ ...form, date: e.target.value })}
        />

        <button onClick={bookOP}>Book OP</button>
      </div>

      <hr />

      {/* PATIENT VIEW (ONLY HIS OP STATUS) */}
      <h3>Your OP Status</h3>

      {queues.map((q) => (
        <div key={q._id} style={{ border: "1px solid gray", margin: 10, padding: 10 }}>

          <p><b>Token:</b> {q.tokenNumber}</p>
          <p><b>Status:</b> {q.status}</p>

          {/* JOIN BUTTON ONLY IF CONFIRMED */}
          {q.status === "Confirmed" && (
            <button onClick={() => joinQueue(q._id)}>
              Join Queue
            </button>
          )}

        </div>
      ))}

    </div>
  );
}

export default PatientDashboard;
